WITH parsed AS (SELECT id, currency, tier_limits, ARRAY_MIN(tier_prices) AS lowest_price, SLICE(tier_limits, 1, 2) AS first_two_limits FROM price_tiers) SELECT CASE WHEN lowest_price >= 27 THEN 'HIGH' ELSE 'LOW' END AS lowest_price_tier, currency, AVG(lowest_price) AS avg_lowest_price, PERCENTILE_APPROX(lowest_price, ARRAY(0.25, 0.5, 0.75)) AS lowest_price_quartiles, SUM(lowest_price) AS total_lowest_price, ROUND(AVG(lowest_price), 2) AS avg_lowest_price_2, COUNT(CASE WHEN currency = 'USD' THEN 1 END) AS usd_count, GROUPING(CASE WHEN lowest_price >= 27 THEN 'HIGH' ELSE 'LOW' END) AS grouping_level FROM parsed GROUP BY GROUPING SETS ((CASE WHEN lowest_price >= 27 THEN 'HIGH' ELSE 'LOW' END, currency), (CASE WHEN lowest_price >= 27 THEN 'HIGH' ELSE 'LOW' END), ()) ORDER BY lowest_price_tier;
